CREATE TABLE sources (id TEXT PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL DEFAULT '', access_state TEXT NOT NULL DEFAULT 'needs_verification', interval_seconds INTEGER NOT NULL DEFAULT 300, config_json TEXT NOT NULL DEFAULT '{}', last_attempt_at TEXT, last_successful_check TEXT, last_result TEXT, coverage TEXT, error TEXT, next_due_at TEXT, failures INTEGER NOT NULL DEFAULT 0, etag TEXT, last_modified TEXT);
CREATE TABLE fetch_runs (id INTEGER PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), started_at TEXT NOT NULL, finished_at TEXT, result TEXT, fetched_count INTEGER NOT NULL DEFAULT 0, changed_count INTEGER NOT NULL DEFAULT 0, invalid_count INTEGER NOT NULL DEFAULT 0, coverage TEXT, error TEXT);
CREATE TABLE documents (id INTEGER PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), identity_key TEXT NOT NULL CHECK(length(identity_key)>0), source_document_id TEXT, url TEXT NOT NULL, first_seen_at TEXT NOT NULL, last_checked_at TEXT NOT NULL, current_version INTEGER NOT NULL DEFAULT 0, UNIQUE(source_id,identity_key));
CREATE TABLE document_versions (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES documents(id), version_number INTEGER NOT NULL, content_hash TEXT NOT NULL, title TEXT NOT NULL, text TEXT NOT NULL, fields_json TEXT NOT NULL, source_published_at TEXT, source_updated_at TEXT, parser_version TEXT NOT NULL, redaction_note TEXT, created_at TEXT NOT NULL, UNIQUE(document_id,version_number));
CREATE TABLE events (id INTEGER PRIMARY KEY, data_json TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, pending_review INTEGER NOT NULL DEFAULT 0, operator_edited INTEGER NOT NULL DEFAULT 0, merged_into INTEGER REFERENCES events(id), created_at TEXT NOT NULL, record_updated_at TEXT NOT NULL);
CREATE TABLE event_evidence (id INTEGER PRIMARY KEY, event_id INTEGER NOT NULL REFERENCES events(id), document_version_id INTEGER NOT NULL REFERENCES document_versions(id), relation TEXT NOT NULL, primary_origin TEXT, supported_fields_json TEXT NOT NULL, excerpt TEXT NOT NULL, UNIQUE(event_id,document_version_id));
CREATE TABLE event_revisions (id INTEGER PRIMARY KEY, event_id INTEGER NOT NULL REFERENCES events(id), version INTEGER NOT NULL, snapshot_json TEXT NOT NULL, at TEXT NOT NULL, actor TEXT NOT NULL, reason TEXT NOT NULL, diff_json TEXT NOT NULL, UNIQUE(event_id,version));
CREATE TABLE review_items (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES documents(id), document_version_id INTEGER NOT NULL REFERENCES document_versions(id), event_id INTEGER REFERENCES events(id), expected_event_version INTEGER NOT NULL DEFAULT 0, proposed_json TEXT NOT NULL, reason TEXT NOT NULL, priority TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, resolved_at TEXT);
CREATE UNIQUE INDEX active_review ON review_items(document_version_id, COALESCE(event_id,0),reason) WHERE state='pending';
CREATE TABLE operator_actions (id INTEGER PRIMARY KEY, action TEXT NOT NULL, event_id INTEGER REFERENCES events(id), review_id INTEGER REFERENCES review_items(id), at TEXT NOT NULL, actor TEXT NOT NULL, reason TEXT NOT NULL, details_json TEXT NOT NULL);
CREATE TABLE app_state (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE INDEX evidence_document ON event_evidence(document_version_id);
CREATE INDEX versions_document ON document_versions(document_id);
CREATE INDEX reviews_state ON review_items(state);
CREATE INDEX events_updated ON events(record_updated_at);
